    daten: body.daten || {},
    herkunft: body.herkunft || {},
    ip,
    einwilligungText: EINWILLIGUNG,
    nutzer,
  });
  return { ok: true, id: ergebnis.id, vorgang: ergebnis.vorgang };
});
